/* Interactive handles and keyboard/numeric alternatives share one curve model. */
window.createDotCurveEditor=function(hooks){'use strict';
const M=window.DotCurve,$=s=>document.querySelector(s),svg=$('.graph'),layer=$('#edit-layer'),ns='http://www.w3.org/2000/svg';let nodes=M.seed(hooks.points()),active=false,chosen=0,part='point',drag=null,addMode=false,history=[];
const px=x=>36+x*240,py=y=>224-y*208;
function el(tag,attrs){const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);return n}
function status(s){$('#editor-status').textContent=s}
function remember(){history.push(JSON.stringify({nodes,chosen,part}));if(history.length>20)history.shift()}
function feedback(){if(hooks.inspect)hooks.inspect(part==='point'?nodes[chosen].x:nodes[chosen][part].x)}
function preview(){if(hooks.preview)hooks.preview()}
function changed(){hooks.change();draw();}
function start(){if(!active){nodes=M.seed(hooks.points());active=true;chosen=0;part='point'}$('#edit-controls').hidden=false;$('#edit-start').textContent='編集中 · CUSTOM';svg.classList.add('editing');hooks.activate();draw();status('点を選んでドラッグ。白いハンドルで加速・減速を調整できます。')}
function reset(){remember();addMode=false;nodes=M.seed(hooks.points(true));chosen=0;part='point';active=true;hooks.activate();changed();status('編集開始時の曲線に戻しました。')}
function draw(){if($('#quick-undo'))$('#quick-undo').disabled=!history.length;layer.replaceChildren();if(!active)return;
const n=nodes[chosen];for(const side of ['in','out']){if(side==='in'&&chosen===0||side==='out'&&chosen===nodes.length-1)continue;const h=n[side];layer.append(el('line',{x1:px(n.x),y1:py(n.y),x2:px(h.x),y2:py(h.y),stroke:'#aaa','stroke-width':1}));const g=el('g',{'data-index':chosen,'data-part':side,class:'edit-target'});g.append(el('circle',{cx:px(h.x),cy:py(h.y),r:18,fill:'transparent'}),el('circle',{cx:px(h.x),cy:py(h.y),r:6.5,fill:part===side?'#fc0':'#111',stroke:'#eee','stroke-width':1.5}));layer.append(g)}
nodes.forEach((p,i)=>{const g=el('g',{'data-index':i,'data-part':'point',class:'edit-target'});g.append(el('circle',{cx:px(p.x),cy:py(p.y),r:18,fill:'transparent'}),el('rect',{x:px(p.x)-6,y:py(p.y)-6,width:12,height:12,rx:1,fill:i===chosen&&part==='point'?'#fc0':'#111',stroke:'#fc0','stroke-width':1.5,transform:`rotate(45 ${px(p.x)} ${py(p.y)})`}));layer.append(g)});
const select=$('#edit-point');select.replaceChildren(...nodes.map((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${String(i+1).padStart(2,'0')} · ${Math.round(p.x*100)}% 時間`;return o}));select.value=chosen;$('#edit-part').value=part;for(const o of $('#edit-part').options)o.disabled=(o.value==='in'&&chosen===0)||(o.value==='out'&&chosen===nodes.length-1);
const p=part==='point'?n:n[part],fixed=part==='point'&&(chosen===0||chosen===nodes.length-1);$('#edit-x').value=(p.x*100).toFixed(1);$('#edit-y').value=(p.y*100).toFixed(1);$('#edit-x').disabled=fixed;$('#edit-y').disabled=fixed;$('#edit-delete').disabled=chosen===0||chosen===nodes.length-1;$('#edit-count').textContent=nodes.length+' / 10 POINTS';$('#edit-add').disabled=nodes.length>=10;$('#edit-at-time').disabled=nodes.length>=10;$('#edit-add').setAttribute('aria-pressed',String(addMode));
}
function update(x,y){if(part==='point')M.move(nodes,chosen,x,y);else M.handle(nodes,chosen,part,x,y);changed()}
function insert(x,y){if(x<=0||x>=1){status('始点と終点は固定です。時間を2〜98%に進めるか、グラフ内を選んでください。');return}const before=JSON.stringify({nodes,chosen,part});const i=M.add(nodes,x,y);if(i<0){status('点は最大10個、時間は隣の点から2%以上離してください。');return}history.push(before);chosen=i;part='point';addMode=false;changed();feedback();status('点を追加しました。選択中の点とハンドルを調整できます。');return true}
function local(e){const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());return{x:M.clamp((point.x-36)/240,0,1),y:M.clamp((224-point.y)/208,0,1)}}
svg.addEventListener('pointerdown',e=>{if(e.button!==0||drag)return;if(!active)start();const target=e.target.closest('[data-index]');if(target){chosen=Number(target.dataset.index);part=target.dataset.part;drag={id:e.pointerId,moved:false,before:JSON.stringify({nodes,chosen,part})};hooks.pause();svg.setPointerCapture(e.pointerId);draw();feedback();e.preventDefault()}else{const p=local(e);if(insert(p.x,p.y)){drag={id:e.pointerId,moved:true};svg.setPointerCapture(e.pointerId)}e.preventDefault()}});
svg.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&drag.before){history.push(drag.before);if(history.length>20)history.shift()}drag.moved=true;const p=local(e);update(p.x,p.y);feedback()});
function finish(e){if(drag&&e.pointerId!==undefined&&e.pointerId!==drag.id)return;if(drag&&e.type==='pointerup'){const moved=drag.moved;if(moved){const p=local(e);update(p.x,p.y);feedback()}drag=null;if(moved)preview()}else drag=null}svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish);svg.addEventListener('lostpointercapture',finish);document.addEventListener('visibilitychange',()=>{if(document.hidden)drag=null});addEventListener('pagehide',()=>{drag=null});
if($('#quick-reset'))$('#quick-reset').addEventListener('click',()=>{reset();feedback();preview()});
if($('#quick-undo'))$('#quick-undo').addEventListener('click',()=>{const previous=history.pop();if(!previous)return;const state=JSON.parse(previous);nodes=state.nodes;chosen=state.chosen;part=state.part;active=true;hooks.activate();changed();feedback();preview();status('ひとつ前の曲線に戻しました。')});
$('#edit-start').addEventListener('click',start);$('#edit-add').addEventListener('click',()=>{addMode=!addMode;draw();status(addMode?'グラフ内の追加したい位置をクリック／タップしてください。':'点の追加をキャンセルしました。')});
$('#edit-at-time').addEventListener('click',()=>insert(hooks.time(),undefined));$('#edit-delete').addEventListener('click',()=>{remember();if(M.remove(nodes,chosen)){chosen=Math.min(chosen,nodes.length-1);part='point';changed();status('選択した点を削除しました。')}});$('#edit-reset').addEventListener('click',reset);
$('#edit-point').addEventListener('change',e=>{chosen=Number(e.target.value);part='point';draw()});$('#edit-part').addEventListener('change',e=>{part=e.target.value;draw()});
function applyNumbers(){const x=$('#edit-x').valueAsNumber/100,y=$('#edit-y').valueAsNumber/100;if(!Number.isFinite(x)||!Number.isFinite(y)){draw();status('0〜100の数値で指定してください。');return}remember();update(x,y);feedback();status('数値を反映しました。時間の前後関係と範囲は自動で保護します。')}
for(const id of ['edit-x','edit-y']){$('#'+id).addEventListener('change',applyNumbers);$('#'+id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();applyNumbers()}})}$('#edit-apply').addEventListener('click',applyNumbers);
$('#editor-keyboard').addEventListener('keydown',e=>{if(!active)return;const p=part==='point'?nodes[chosen]:nodes[chosen][part],step=e.shiftKey?.05:.01;let x=p.x,y=p.y;if(e.key==='ArrowLeft')x-=step;else if(e.key==='ArrowRight')x+=step;else if(e.key==='ArrowUp')y+=step;else if(e.key==='ArrowDown')y-=step;else return;e.preventDefault();remember();update(x,y);feedback()});
return {boot(){start();chosen=M.add(nodes,.5);part='point';draw();hooks.change();history=[];draw();},path:()=>nodes.map((n,i)=>i?`C${px(nodes[i-1].out.x)} ${py(nodes[i-1].out.y)} ${px(n.in.x)} ${py(n.in.y)} ${px(n.x)} ${py(n.y)}`:`M${px(n.x)} ${py(n.y)}`).join(' '),value:t=>M.value(nodes,t),rate:t=>M.rate(nodes,t),isActive:()=>active,refresh:draw,leave(){active=false;drag=null;addMode=false;history=[];if($('#quick-undo'))$('#quick-undo').disabled=true;$('#curve-select option[value=custom]').disabled=true;$('#edit-controls').hidden=true;$('#edit-start').textContent='この曲線を編集する ↗';svg.classList.remove('editing');layer.replaceChildren();status('プリセット切替・再読み込みで編集内容は消えます。')},count:()=>nodes.length};
};
